const PAT = 'AIRTABLE_PAT_REDACTED';
const BASE_ID = 'appP4FfGtulxFG1wq';
const TABLE_ID = 'tblbIbuVqSt0BnYZj';

const body = $input.first().json.body || $input.first().json;

// honeypot: bots fill the hidden field
if (body._hp) {
  return [{ json: { ok: true } }];
}

const required = ['restaurantName', 'ownerName', 'ownerEmail'];
for (const f of required) {
  if (!body[f] || !String(body[f]).trim()) {
    return [{ json: { ok: false, error: 'Missing required field: ' + f } }];
  }
}

const s = v => (v == null ? '' : String(v).trim());
const fields = {
  'Restaurant Name': s(body.restaurantName),
  'Submitted At': new Date().toISOString(),
  'Status': 'New',
  'Legal Business Name': s(body.legalName),
  'EIN': s(body.ein),
  'Owner Name': s(body.ownerName),
  'Owner Phone': s(body.ownerPhone),
  'Owner Email': s(body.ownerEmail),
  'Website': s(body.website),
  'Locations': s(body.locations),
  'Phone Provider': s(body.phoneProvider),
  'Has Portal Access': s(body.portalAccess),
  'Forwarding Mode': s(body.forwardingMode),
  'Online Ordering URL': s(body.orderingUrl),
  'Menu Contact': s(body.menuContact),
  'Prices Differ By Location': body.pricesDiffer === true || body.pricesDiffer === 'yes',
  'Excluded Items': s(body.excludedItems),
  'Assistant Name': s(body.assistantName),
  'Greeting': s(body.greeting),
  'Tone': s(body.tone),
  'Languages': Array.isArray(body.languages) ? body.languages : [],
  'Top FAQs': s(body.faqs),
  'Dashboard Monitor': s(body.monitorName),
  'Monitor Device': s(body.monitorDevice),
  'Default Pickup Time': s(body.pickupTime),
  'Rejection Reasons': s(body.rejectionReasons),
  'Escalation Phone': s(body.escalationPhone),
  'SMS Consent Approved': body.smsConsent === true || body.smsConsent === 'yes',
  'Menu Review Acknowledged': body.menuAck === true || body.menuAck === 'yes',
  'Notes': s(body.notes),
};
// drop empty optional selects so Airtable doesn't reject unknown ''
for (const k of ['Has Portal Access','Forwarding Mode','Tone','Monitor Device','Website','Online Ordering URL']) {
  if (!fields[k]) delete fields[k];
}

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.airtable.com/v0/' + BASE_ID + '/' + TABLE_ID,
  headers: { Authorization: 'Bearer ' + PAT, 'Content-Type': 'application/json' },
  body: { records: [{ fields }], typecast: true },
  json: true,
});

return [{ json: { ok: true, id: res.records[0].id } }];
